import { merge } from "@lumeland/core/utils/object.ts";
export const defaults = {
    remove: true,
    cascade: false,
};
const ORDER_REGEX = /(\d+)\.(.+)/;
/**
 * A plugin to extract the order from the files and folders paths
 * @see https://lume.land/plugins/extract-order/
 */
export function extractOrder(userOptions) {
    const options = merge(defaults, userOptions);
    return (site) => {
        site.parseBasename((name, parent) => {
            const match = name.match(ORDER_REGEX);
            if (match) {
                let [, order, basename] = match;
                if (options.cascade) {
                    order = `${parent.order ?? ""}${order.padStart(2, "0")}`;
                }
                if (!options.remove) {
                    basename = name;
                }
                return { order: Number(order), basename };
            }
        });
    };
}
export default extractOrder;
